const body = $json.body || $json;
const amountSgd = Number(body.amount_sgd || body.amountSgd || 0);
const invoicePublicId = String(body.invoice_public_id || body.invoicePublicId || '');

if (!invoicePublicId || !Number.isFinite(amountSgd) || amountSgd <= 0) {
  return [{
    json: {
      success: false,
      error: 'invoice_public_id and a positive amount_sgd are required'
    }
  }];
}

const fallbackRate = Number($env.QUOTE_SGD_PER_ETH || 4800);
const quoteBufferPct = Number($env.QUOTE_BUFFER_PCT || 0.75);
const effectiveRate = fallbackRate * (1 + quoteBufferPct / 100);
const requiredCrypto = amountSgd / effectiveRate;

return [{
  json: {
    success: true,
    invoice_public_id: invoicePublicId,
    amount_sgd: Number(amountSgd.toFixed(2)),
    sgd_per_eth_rate: Number(effectiveRate.toFixed(6)),
    required_crypto_amount: requiredCrypto.toFixed(18),
    quote_source: 'n8n-local-quote',
    quote_buffer_pct: quoteBufferPct,
    expires_in_seconds: 300,
    quoted_at: new Date().toISOString()
  }
}];
